class Solution {
    public String minWindow(String s, String t) {
        int n = s.length(), m = t.length();
        if (n == 0 || m > n) return "";

        int[] need = new int[128];
        for (char c : t.toCharArray()) need[c]++;

        int bestLen = Integer.MAX_VALUE, bestStart = 0;
        for (int left = 0; left < n; left++) {
            int[] cnt = new int[128];
            for (int right = left; right < n; right++) {
                cnt[s.charAt(right)]++;
                if (right - left + 1 >= m && covers(cnt, need)) {
                    if (right - left + 1 < bestLen) {
                        bestLen = right - left + 1;
                        bestStart = left;
                    }
                    break;   // 以 left 开头的再长也不会更优
                }
            }
        }
        return bestLen == Integer.MAX_VALUE ? "" : s.substring(bestStart, bestStart + bestLen);
    }

    // cnt 是否覆盖 need：need 里每个字符的数量都要够
    private boolean covers(int[] cnt, int[] need) {
        for (int i = 0; i < 128; i++) {
            if (cnt[i] < need[i]) return false;
        }
        return true;
    }
}

class Solution {
    public String minWindow(String s, String t) {
        int n = s.length(), m = t.length();
        if (n == 0 || m > n) return "";

        int[] need = new int[128];
        for (char c : t.toCharArray()) need[c]++;

        int[] window = new int[128];
        int left = 0;
        int bestLen = Integer.MAX_VALUE, bestStart = 0;

        for (int right = 0; right < n; right++) {
            window[s.charAt(right)]++;
            // 满足覆盖就不断收缩左边界
            while (covers(window, need)) {
                if (right - left + 1 < bestLen) {
                    bestLen = right - left + 1;
                    bestStart = left;
                }
                window[s.charAt(left)]--;
                left++;
            }
        }
        return bestLen == Integer.MAX_VALUE ? "" : s.substring(bestStart, bestStart + bestLen);
    }

    private boolean covers(int[] window, int[] need) {
        for (int i = 0; i < 128; i++) {
            if (window[i] < need[i]) return false;
        }
        return true;
    }
}

class Solution {
    public String minWindow(String s, String t) {
        int n = s.length(), m = t.length();
        if (n == 0 || m > n) return "";

        int[] need = new int[128];
        for (char c : t.toCharArray()) need[c]++;

        int required = 0;
        for (int i = 0; i < 128; i++) if (need[i] > 0) required++;

        int[] window = new int[128];
        int left = 0, formed = 0;
        int bestLen = Integer.MAX_VALUE, bestStart = 0;

        for (int right = 0; right < n; right++) {
            char c = s.charAt(right);
            window[c]++;
            // 这一种字符刚好凑够数量了
            if (need[c] > 0 && window[c] == need[c]) formed++;

            // 窗口合法，尝试收缩
            while (formed == required) {
                if (right - left + 1 < bestLen) {
                    bestLen = right - left + 1;
                    bestStart = left;
                }
                char d = s.charAt(left);
                // 这一种字符马上要不够了
                if (need[d] > 0 && window[d] == need[d]) formed--;
                window[d]--;
                left++;
            }
        }
        return bestLen == Integer.MAX_VALUE ? "" : s.substring(bestStart, bestStart + bestLen);
    }
}
